-- 92 Crane Yard: a crane truck made of joints. Its wheels are wheel
-- joints (sprung and driven), the trolley a prismatic joint along the boom,
-- the hook a rope whose swing a friction joint damps; Space holds the crate
-- under the hook with a motor joint (an offset with limited strength) and
-- the mouse drags crates with target joints. Joints made at run time are
-- Physics.add_joint's JSON - the same shape a scene file uses. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/92-crane-yard.scene"
local MASS = { Crate0 = 20.0, Crate1 = 20.0, Crate2 = 20.0, Crate3 = 20.0, Crate4 = 60.0 }
local HEIGHT = { Crate0 = 60.0, Crate1 = 60.0, Crate2 = 60.0, Crate3 = 60.0, Crate4 = 52.0 }
local G = 981

local captions = true
local e = {}
local crates = {}        -- id -> name
local rope = 120.0
local winch_t = 0
local held = nil         -- the crate the magnet holds
local dragged = nil      -- the crate the mouse holds
local frame = 0

local function joint_json(target, kind, fields)
    return string.format('{"target_entity":"%s","collide_connected":false,"joint_type":{"%s":%s}}',
        target, kind, fields)
end

-- The hook: a rope to the trolley, and friction against it so a swing dies
-- away instead of going on for ever.
local function hang_hook()
    Physics.remove_joint("Hook")
    Physics.add_joint("Hook", "Trolley", joint_json("Trolley", "Rope",
        string.format('{"anchor_a":[0,25],"anchor_b":[0,-10],"max_distance":%.1f}', rope)))
    Physics.add_joint("Hook", "Trolley", joint_json("Trolley", "Friction",
        '{"max_force":2500,"max_torque":60000}'))
end

local function let_go(name)
    Physics.remove_joint(name)
    if held == name then held = nil end
    if dragged == name then dragged = nil end
end

local function crate_at(list)
    for _, id in ipairs(list or {}) do
        if crates[id] then return crates[id] end
    end
    return nil
end

function init(entity)
    for _, n in ipairs({ "Chassis", "Trolley", "Hook", "Cable", "Cursor" }) do e[n] = Entity.find_by_name(n) end
    for name, _ in pairs(MASS) do
        local id = Entity.find_by_name(name)
        e[name] = id
        crates[id] = name
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    -- The bodies exist from the first physics step; rehang the hook (adding
    -- its friction) once they do.
    frame = frame + 1
    if frame == 3 then hang_hook() end

    -- Drive: both wheels' motors; at 0 the motors hold the truck still.
    local drive = 0
    if Input.is_key_pressed("Left") then drive = drive - 7 end
    if Input.is_key_pressed("Right") then drive = drive + 7 end
    Physics.set_motor_speed("Rear", drive)
    Physics.set_motor_speed("Front", drive)

    -- The trolley slides along the boom on its prismatic motor.
    local slide = 0
    if Input.is_key_pressed("Q") then slide = slide - 140 end
    if Input.is_key_pressed("E") then slide = slide + 140 end
    Physics.set_motor_speed("Trolley", slide)

    -- The winch: a new rope, a little longer or shorter.
    winch_t = winch_t + dt
    local winch = 0
    if Input.is_key_pressed("S") then winch = 1 end
    if Input.is_key_pressed("W") then winch = -1 end
    if winch ~= 0 and winch_t > 0.05 then
        winch_t = 0
        rope = math.max(50, math.min(300, rope + winch * 8))
        hang_hook()
    end

    -- The magnet: a motor joint holds the crate under the hook, as strong as
    -- two and a half times its weight - a container sags and sways on it.
    if Input.is_key_just_pressed("Space") then
        if held then
            let_go(held)
        else
            local hx, hy = Transform.get_position(e.Hook)
            local name = crate_at(Physics.overlap_circle(hx, hy - 50, 40))
            if name then
                let_go(name)
                held = name
                Physics.add_joint(name, "Hook", joint_json("Hook", "Motor", string.format(
                    '{"linear_offset":[0,%.1f],"max_force":%.0f,"max_torque":3000000,"frequency":3,"damping_ratio":0.5}',
                    -(25 + HEIGHT[name] / 2 + 1), MASS[name] * G * 2.5)))
            end
        end
    end

    -- The mouse: a target joint pulls the crate it grabbed toward the cursor.
    local mx, my = Input.get_mouse_world_position()
    Transform.set_position(e.Cursor, mx, my)
    if Input.is_mouse_left_just_pressed() then
        local name = crate_at(Physics.overlap_point(mx, my))
        if name then
            local cx, cy = Transform.get_position(e[name])
            let_go(name)
            dragged = name
            -- Grabbed where the mouse is, not by the middle (unturned: near
            -- enough for a crate that is mostly upright).
            Physics.add_joint(name, "Cursor", joint_json("Cursor", "Target", string.format(
                '{"anchor":[%.1f,%.1f],"frequency":4,"damping_ratio":0.7,"max_force":%.0f}',
                mx - cx, my - cy, MASS[name] * G * 4)))
        end
    end
    if dragged and not Input.is_mouse_left_pressed() then let_go(dragged) end

    -- The cable, from the trolley to the hook.
    local tx, ty = Transform.get_position(e.Trolley)
    local hx, hy = Transform.get_position(e.Hook)
    Line.set(e.Cable, "points", { { tx, ty - 10 }, { hx, hy + 25 } })
end
